347	/** Hard cap on parser input — a JD email is never this long; prevents any
348	 *  pathological-input CPU blowup regardless of caller. */
349	const MAX_PARSE_CHARS = 20000;
350	
351	export function parseEmailAndJD(input: { email: string; jd?: string }): ParsedIntake {
352	  const text = `${input.email}\n${input.jd ?? ""}`.slice(0, MAX_PARSE_CHARS);
353	  const lower = text.toLowerCase();
354	
355	  // Structured Mantu/Amaris "need is now ACTIVE" email → dedicated parser.
356	  if (isMantuNeedEmail(text)) return parseMantuNeed(text);
357	
358	  // Sender extraction
359	  const emailMatch = text.match(/[A-Za-z0-9._+-]{1,128}@[A-Za-z0-9-]{1,128}\.[A-Za-z0-9.-]{1,64}/);
360	  const fromLine = text.match(/from:\s*(.+)/i)?.[1] ?? "";
361	  const nameMatch =
362	    fromLine.match(/^([A-Z][a-z]+ [A-Z][a-z]+)/)?.[1] ??
363	    text.match(/(?:thanks|regards|best|cheers)[,\s]+\n?\s*([A-Z][a-z]+ [A-Z][a-z]+)/)?.[1] ??
364	    "Hiring Manager";
365	  const senderEmail = emailMatch?.[0] ?? "unknown@company.example";
366	
367	  // Intent
368	  let intent: IntakeIntent = "New Role";
369	  if (/backfill|replace|left the team|departure|resign/i.test(text)) intent = "Backfill";
370	  else if (/asap|urgent|immediately|yesterday|critical/i.test(text)) intent = "Urgent Hire";
371	  else if (/exploratory|pipeline|future|keep warm|no rush/i.test(text)) intent = "Exploratory";
372	
373	  // Urgency
374	  let urgency: Urgency = "Standard";
375	  if (/\basap\b|immediately|yesterday/i.test(text)) urgency = "ASAP";
376	  else if (/critical|p0|blocking/i.test(text)) urgency = "Critical";
377	  else if (/urgent|high priority|priority/i.test(text)) urgency = "Urgent";
378	  else if (/this week|by friday|next few days/i.test(text)) urgency = "This Week";
379	
380	  // Title
381	  const titleMatch =
382	    text.match(/(?:hiring|looking for|need|seeking|backfill)\s+(?:an?\s+)?([A-Z][\w/ +.-]{3,48}?(?:Engineer|Developer|Designer|Manager|Lead|Architect|Scientist|Analyst))/i)?.[1] ??
383	    text.match(/(?:role|position|title):\s*(.+)/i)?.[1] ??
384	    "Senior Software Engineer";
385	  const title = titleMatch.trim().replace(/\s+/g, " ");
386	
387	  // Seniority
388	  let seniority: Seniority = "Senior";
389	  if (/principal/i.test(title)) seniority = "Principal";
390	  else if (/staff/i.test(title)) seniority = "Staff";
