 17	/**
 18	 * Intake API / email-scan endpoint.
 19	 *
 20	 * An inbound email integration (Microsoft Graph subscription, a forwarding rule,
 21	 * n8n, Zapier, …) POSTs a received job-description email here and gets back a
 22	 * structured JobAnalysis + suggested hiring-manager meta. The client then creates
 23	 * the campaign (human-in-the-loop) — parsing never auto-sends or auto-contacts.
 24	 *
 25	 * Body (either shape):
 26	 *   { "email": "<raw email text>", "jd": "<optional JD text>" }
 27	 *   { "from": "...", "subject": "...", "body": "<email body>" }
 28	 *
 29	 * Auth: required when Supabase is configured; open in demo mode (it only parses
 30	 * text the caller supplies — no data access).
 31	 */
 32	export async function GET() {
 33	  return NextResponse.json({
 34	    ok: true,
 35	    usage: "POST { email, jd? } or { from, subject, body } to parse a JD email into a structured JobAnalysis.",
 36	  });
 37	}
