 39	export async function POST(req: NextRequest) {
 40	  // Fail closed in production: middleware does not run on /api/*, so refuse here
 41	  // rather than fall back to open demo mode when Supabase is unconfigured in prod.
 42	  const prodBlock = prodFailClosed();
 43	  if (prodBlock) return prodBlock;
 44	
 45	  // Auth-first: gate before parsing or returning anything when a real backend
 46	  // exists. Demo mode is open (pure text parsing of caller-supplied input).
 47	  if (supabaseEnabled) {
 48	    const supabase = await getServerSupabase();
 49	    const { data } = (await supabase?.auth.getUser()) ?? { data: { user: null } };
 50	    if (!data?.user) {
 51	      return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
 52	    }
 53	  }
 54	
 55	  // Throttle: parsing runs an LLM-style extraction — cost/abuse-prone. Tight limit.
 56	  const limit = checkRateLimit(rateLimitKey(req, "intake"), { windowMs: 60_000, max: 10 });
 57	  if (!limit.ok) return tooManyRequests(limit.retryAfterSec);
 58	
 59	  const validated = await validateBody(req, IntakeSchema, { maxBytes: 64_000 });
 60	  if (!validated.ok) return validated.response;
 61	  const payload = validated.data;
 62	
 63	  // Accept {email,jd} or {from,subject,body}
 64	  const email =
 65	    payload.email && payload.email.trim()
 66	      ? payload.email
 67	      : [payload.from ? `From: ${payload.from}` : "", payload.subject ? `Subject: ${payload.subject}` : "", payload.body ?? ""]
 68	          .filter(Boolean)
 69	          .join("\n");
 70	  const jd = payload.jd;
 71	
 72	  if (!email.trim()) {
 73	    return NextResponse.json({ ok: false, error: "Provide `email` (or `from`/`subject`/`body`)." }, { status: 400 });
 74	  }
 75	
 76	  const parsed = parseEmailAndJD({ email, jd });
 77	  return NextResponse.json({
 78	    ok: true,
 79	    format: isMantuNeedEmail(email) ? "mantu-need" : "generic",
 80	    parsed,
 81	    suggestedMeta: {
 82	      hiringManager: parsed.sender.name,
 83	      hiringManagerEmail: parsed.sender.email,
 84	    },
 85	  });
 86	}
