 15	/**
 16	 * Real candidate sourcing.
 17	 *
 18	 * platform "GitHub" (default): searches GitHub for real people via the Users
 19	 * Search API. Runs keyless by default (GitHub's anonymous API quota, 60
 20	 * req/hour/IP) — no signup required. An optional GITHUB_TOKEN, resolved
 21	 * server-side and never returned to the client, raises that ceiling to 5,000
 22	 * req/hour.
 23	 *
 24	 * platform in {LinkedIn, Stack Overflow, Dribbble, Behance}: no free structured
 25	 * search API exists for these, so real candidates are discovered via the
 26	 * existing compliant web_search tool (site:-scoped), same honesty/read-only
 27	 * guarantees as the chat research tools.
 28	 *
 29	 * platform in {Referral, Talent Pool}: not externally sourceable — these are
 30	 * internal-pipeline concepts, not searched at all.
 31	 *
 32	 * Read-only throughout: never writes to GitHub, never logs into or scrapes a
 33	 * platform, never posts a message.
 34	 *
 35	 * `username` (optional): manual single-profile intake. When present, `query`
 36	 * is ignored entirely and the request resolves that one GitHub login via
 37	 * GET /users/{login} instead of running a search.
 38	 */
 39	const GITHUB_USERNAME_RE = /^[a-zA-Z\d](?:[a-zA-Z\d]|-(?=[a-zA-Z\d])){0,38}$/;
