 59	export async function POST(req: NextRequest) {
 60	  const prodBlock = prodFailClosed();
 61	  if (prodBlock) return prodBlock;
 62	  const demoBlock = publicDemoSourceDenied(req);
 63	  if (demoBlock) return demoBlock;
 64	
 65	  const rl = checkRateLimit(rateLimitKey(req, "source"), { windowMs: 60_000, max: 10 });
 66	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
 67	
 68	  // Live mode: require an authenticated user with the `source` permission. Demo
 69	  // mode (no backend) is open but still rate-limited.
 70	  if (supabaseEnabled) {
 71	    const supabase = await getServerSupabase();
 72	    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
 73	    const {
 74	      data: { user },
 75	    } = await supabase.auth.getUser();
 76	    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
 77	    const { data: role } = await supabase.rpc("current_profile_role");
 78	    if (!can(role as Role, "source")) {
 79	      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
 80	    }
 81	  }
 82	
 83	  const validated = await validateBody(req, SourceSchema, { maxBytes: 10_000 });
 84	  if (!validated.ok) return validated.response;
 85	  const { query, username, count = 8, platform = "GitHub" as const } = validated.data;
 86	
 87	  // Manual single-profile intake: resolve exactly the named GitHub login,
 88	  // ignoring `query` and `count` entirely — this is a lookup, not a search.
 89	  if (username) {
 90	    const token = process.env.GITHUB_TOKEN ?? "";
 91	    try {
 92	      const user = await getGithubUser(username, token);
 93	      if (!user) {
 94	        return NextResponse.json({ ok: false, error: "GitHub user not found." }, { status: 404 });
 95	      }
 96	      return NextResponse.json({ ok: true, source: "github", users: [user] });
 97	    } catch (err) {
 98	      const detail = err instanceof Error ? err.message : "GitHub lookup failed.";
 99	      return NextResponse.json({ ok: false, source: "github", error: detail }, { status: 502 });
100	    }
101	  }
102	
103	  // Schema-enforced: username or query is present; username was handled above.
104	  if (!query) return NextResponse.json({ ok: false, error: "query is required." }, { status: 400 });
105	
106	  if (platform === "GitHub") {
107	    const token = process.env.GITHUB_TOKEN ?? "";
108	    try {
109	      const users = await searchGithubUsers(query, count, token);
110	      return NextResponse.json({ ok: true, source: "github", platform, users });
111	    } catch (err) {
112	      // GitHub error bodies never contain the token; keep the client message terse.
113	      const detail = err instanceof Error ? err.message : "GitHub search failed.";
114	      return NextResponse.json({ ok: false, source: "github", platform, error: detail }, { status: 502 });
115	    }
116	  }
117	
118	  if (isWebSearchPlatform(platform)) {
119	    const result = await runWebTool("web_search", { query });
120	    if (!result.ok) {
121	      return NextResponse.json(
122	        { ok: false, source: "web", platform, error: result.error ?? "Web search failed." },
123	        { status: 502 },
124	      );
125	    }
126	    const content = result.content as { results?: { title: string; url: string; snippet: string }[] } | undefined;
127	    const hits = (content?.results ?? []).slice(0, count);
128	    const leads: WebLead[] = hits.map((h) => extractLead(h, platform));
129	    return NextResponse.json({ ok: true, source: "web", platform, leads });
130	  }
131	
132	  // Referral / Talent Pool: internal-pipeline concepts, no external source to search.
133	  return NextResponse.json({ ok: true, source: "mock", platform, users: [] as GithubUser[] });
134	}
