  50	/** Encrypt a secret for storage. Returns the plaintext unchanged when no key is set. */
  51	export function encryptSecret(plaintext: string): string {
  52	  const key = getKey();
  53	  if (!key || !plaintext) return plaintext;
  54	  const iv = randomBytes(12);
  55	  const cipher = createCipheriv("aes-256-gcm", key, iv);
  56	  const ct = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
  57	  const tag = cipher.getAuthTag();
  58	  return `${PREFIX}${iv.toString("base64")}:${tag.toString("base64")}:${ct.toString("base64")}`;
  59	}
