  61	/** Decrypt a stored secret. Legacy plaintext (or no key) passes through unchanged. An
  62	 *  encrypted value with no/invalid key fails closed (empty string). */
  63	export function decryptSecret(stored: string): string {
  64	  if (!stored || !stored.startsWith(PREFIX)) return stored; // legacy plaintext
  65	  const key = getKey();
  66	  if (!key) return "";
  67	  try {
  68	    const [ivB64, tagB64, ctB64] = stored.slice(PREFIX.length).split(":");
  69	    if (!ivB64 || !tagB64 || !ctB64) return "";
  70	    const decipher = createDecipheriv("aes-256-gcm", key, Buffer.from(ivB64, "base64"));
  71	    decipher.setAuthTag(Buffer.from(tagB64, "base64"));
  72	    return Buffer.concat([decipher.update(Buffer.from(ctB64, "base64")), decipher.final()]).toString("utf8");
  73	  } catch {
  74	    return "";
  75	  }
  76	}
