197	export async function resolveStoredApolloKey(
198	  session: NonNullable<Awaited<ReturnType<typeof getServerSupabase>>>,
199	): Promise<string | null> {
200	  const svc = getServiceSupabase();
201	  if (!svc) return null;
202	  const { data: wid } = await session.rpc("current_workspace_id");
203	  if (!wid) return null;
204	  const { data: row } = await svc
205	    .from("api_keys")
206	    .select("secret")
207	    .eq("workspace_id", wid)
208	    .eq("provider", "Apollo")
209	    .order("created_at", { ascending: false })
210	    .limit(1)
211	    .maybeSingle();
212	  if (!row?.secret || typeof row.secret !== "string") return null;
