 84	  apiKey: string,
 85	  opts: { method?: "GET" | "POST"; body?: unknown; timeoutMs?: number } = {},
 86	): Promise<SillageResult<T>> {
 87	  try {
 88	    const res = await fetch(`${SILLAGE_API}${path}`, {
 89	      method: opts.method ?? "GET",
 90	      headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json", Accept: "application/json" },
 91	      body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
 92	      signal: AbortSignal.timeout(opts.timeoutMs ?? 15_000),
 93	    });
 94	    const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
 95	    if (!res.ok) {
 96	      const title = typeof json.title === "string" ? json.title : `Sillage API error (${res.status})`;
 97	      const detail =
 98	        typeof json.detail === "string" ? json.detail : typeof json.message === "string" ? json.message : "";
 99	      return { ok: false, status: res.status, title, detail };
100	    }
101	    return { ok: true, status: res.status, data: json as T };
102	  } catch (err) {
103	    const message = err instanceof Error ? err.message : "Sillage unreachable.";
104	    return { ok: false, status: 0, title: "Network error", detail: message };
