 75	
 76	function concat(chunks: Uint8Array[], total: number): Uint8Array {
 77	  const out = new Uint8Array(total);
 78	  let o = 0;
 79	  for (const c of chunks) {
 80	    out.set(c, o);
 81	    o += c.length;
 82	  }
 83	  return out;
 84	}
