 86	/** Read a response body up to `maxBytes`, cancelling the stream once the cap is hit. */
 87	async function readCapped(res: Response, maxBytes: number): Promise<string> {
 88	  const reader = res.body?.getReader();
 89	  if (!reader) return (await res.text()).slice(0, maxBytes);
 90	  const chunks: Uint8Array[] = [];
 91	  let total = 0;
 92	  for (;;) {
 93	    const { done, value } = await reader.read();
 94	    if (done) break;
 95	    if (value) {
 96	      chunks.push(value);
 97	      total += value.length;
 98	      if (total >= maxBytes) {
 99	        await reader.cancel().catch(() => {});
100	        break;
101	      }
102	    }
103	  }
104	  return new TextDecoder("utf-8", { fatal: false }).decode(concat(chunks, total)).slice(0, maxBytes);
105	}
