107	function decodeEntities(s: string): string {
108	  return s
109	    .replace(/&amp;/g, "&")
110	    .replace(/&lt;/g, "<")
111	    .replace(/&gt;/g, ">")
112	    .replace(/&quot;/g, '"')
113	    .replace(/&#0*39;/g, "'")
114	    .replace(/&apos;/g, "'")
115	    .replace(/&nbsp;/g, " ");
116	}
