118	/** Strip HTML to a title + collapsed plain-text body. */
119	export function stripHtml(html: string): { title: string; text: string } {
120	  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
121	  const title = decodeEntities((titleMatch?.[1] ?? "").replace(/\s+/g, " ").trim()).slice(0, 200);
122	  const text = decodeEntities(
123	    html
124	      .replace(/<script[\s\S]*?<\/script>/gi, " ")
125	      .replace(/<style[\s\S]*?<\/style>/gi, " ")
126	      .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
127	      .replace(/<!--[\s\S]*?-->/g, " ")
128	      .replace(/<[^>]+>/g, " "),
129	  )
130	    .replace(/\s+/g, " ")
131	    .trim();
132	  return { title, text };
133	}
