135	/** SSRF-guarded, read-only GET with redirect + timeout + size caps. */
136	async function safeGet(
137	  url: string,
138	  accept: string,
139	): Promise<{ ok: boolean; body?: string; error?: string }> {
140	  const guard = await assertPublicUrl(url);
141	  if (!guard.ok) return { ok: false, error: guard.reason ?? "URL blocked." };
142	  let res: Response;
143	  try {
144	    res = await fetch(url, {
145	      method: "GET",
146	      headers: { accept, "user-agent": USER_AGENT },
147	      redirect: "manual",
148	      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
149	    });
150	  } catch (err) {
151	    return { ok: false, error: err instanceof Error ? err.message : "Network error." };
152	  }
153	  if (res.type === "opaqueredirect" || (res.status >= 300 && res.status < 400)) {
154	    return { ok: false, error: "Redirect blocked (SSRF guard)." };
155	  }
156	  if (!res.ok) return { ok: false, error: `HTTP ${res.status}` };
157	  return { ok: true, body: await readCapped(res, MAX_BYTES) };
158	}
