178	    });
179	    if (!res.ok) return null;
180	    const data = (await res.json().catch(() => null)) as
181	      | { results?: { title?: string; url?: string; content?: string }[] }
182	      | null;
183	    const results: SearchHit[] = (data?.results ?? [])
184	      .filter((r) => r.url)
185	      .slice(0, MAX_RESULTS)
186	      .map((r) => ({ title: (r.title ?? "").slice(0, 120), url: r.url as string, snippet: (r.content ?? "").slice(0, 300) }));
