193	async function webSearch(queryRaw: string): Promise<ToolResult> {
194	  const query = queryRaw.trim().slice(0, 300);
195	  if (!query) return { ok: false, error: "Empty query." };
196	
197	  // Prefer an official search API when configured.
198	  const tavilyKey = process.env.TAVILY_API_KEY;
199	  if (tavilyKey) {
200	    const t = await tavilySearch(query, tavilyKey);
201	    if (t) return t;
202	  }
203	
204	  // Key-less default: DuckDuckGo Instant Answer JSON API (public, documented).
205	  const r = await safeGet(
206	    `https://api.duckduckgo.com/?q=${encodeURIComponent(query)}&format=json&no_html=1&no_redirect=1&t=aria`,
207	    "application/json",
208	  );
209	  if (!r.ok) return { ok: false, error: r.error };
210	  let data: {
211	    Heading?: string;
212	    AbstractText?: string;
213	    AbstractURL?: string;
214	    RelatedTopics?: { FirstURL?: string; Text?: string; Topics?: { FirstURL?: string; Text?: string }[] }[];
215	  };
216	  try {
217	    data = JSON.parse(r.body ?? "{}");
218	  } catch {
219	    return { ok: false, error: "Malformed search response." };
220	  }
221	  const results: SearchHit[] = [];
222	  if (data.AbstractText && data.AbstractURL) {
223	    results.push({ title: (data.Heading || query).slice(0, 120), url: data.AbstractURL, snippet: data.AbstractText.slice(0, 300) });
224	  }
225	  for (const topic of data.RelatedTopics ?? []) {
226	    const flat = topic.Topics ?? [topic];
227	    for (const it of flat) {
228	      if (results.length >= MAX_RESULTS) break;
229	      if (it.FirstURL && it.Text) {
230	        results.push({ title: it.Text.slice(0, 120), url: it.FirstURL, snippet: it.Text.slice(0, 300) });
231	      }
232	    }
233	    if (results.length >= MAX_RESULTS) break;
234	  }
235	  return { ok: true, content: { query, results, source: "duckduckgo" } };
236	}
