250	/** Extract the inner text of the first `<tag>…</tag>` (handles CDATA). */
251	function tagText(block: string, tag: string): string {
252	  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, "i"));
253	  if (!m) return "";
254	  const inner = m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1");
255	  return decodeEntities(inner.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim());
256	}
257	
258	/** Atom feeds use `<link href="…"/>`; pull the href when present. */
259	function linkHref(block: string): string {
260	  const m = block.match(/<link\b[^>]*href=["']([^"']+)["']/i);
261	  return m ? decodeEntities(m[1]) : "";
262	}
263	
264	async function rss(urlRaw: string): Promise<ToolResult> {
265	  const url = urlRaw.trim();
266	  if (!url) return { ok: false, error: "Missing url." };
267	  const r = await safeGet(url, "application/rss+xml,application/atom+xml,application/xml,text/xml");
268	  if (!r.ok) return { ok: false, error: r.error };
269	  const xml = r.body ?? "";
270	  const blocks = xml.match(/<(item|entry)\b[\s\S]*?<\/\1>/gi) ?? [];
271	  const items = blocks.slice(0, 15).map((b) => ({
272	    title: tagText(b, "title").slice(0, 200),
273	    link: (tagText(b, "link") || linkHref(b)).slice(0, 500),
274	    date: (tagText(b, "pubDate") || tagText(b, "updated") || tagText(b, "published")).slice(0, 60),
275	    summary: (tagText(b, "description") || tagText(b, "summary") || tagText(b, "content")).slice(0, 300),
276	  }));
277	  return { ok: true, content: { url, count: items.length, items } };
278	}
