 23	export const SOURCING_TOOL_DEFS: McpTool[] = [
 24	  {
 25	    name: "search_candidates",
 26	    description:
 27	      "Search ONE platform for real candidates matching this role, already deduped and scored " +
 28	      "against the job description. Returns real people found via that platform's real search " +
 29	      "(GitHub's Search API, or a site:-scoped web search for the others) — never fabricated. " +
 30	      "Call it once per platform worth checking; call it again with a different query on the same " +
 31	      "platform to broaden a search that returned too few good matches.",
 32	    inputSchema: {
 33	      type: "object",
 34	      properties: {
 35	        platform: {
 36	          type: "string",
 37	          enum: ["GitHub", "LinkedIn", "Stack Overflow", "Dribbble", "Behance"],
 38	          description: "Which platform to search.",
 39	        },
 40	        query: {
 41	          type: "string",
 42	          description:
 43	            "GitHub: a GitHub search-qualifier string (e.g. 'language:Go followers:>40'). " +
 44	            "Others: plain keywords (title + a skill) — this gets scoped with a site: filter automatically.",
 45	        },
 46	        count: { type: "number", description: "Max candidates to return this call (1-10). Default 5." },
 47	      },
