 53	export function isSourcingTool(name: string): boolean {
 54	  return name === "search_candidates";
 55	}
 56	
 57	interface SearchSummary {
 58	  id: string;
 59	  name: string;
 60	  currentTitle: string;
 61	  currentCompany: string;
 62	  location: string;
 63	  matchScore: number;
 64	  sourcePlatform: SourcePlatform;
 65	  url: string;
 66	  techStack: string[];
 67	  recentActivity: string;
 68	}
