 70	/**
 71	 * Build a stateful search_candidates runner bound to one campaign/request.
 72	 * `run` dispatches the tool call; `getFound()` returns every real, scored
 73	 * Candidate accumulated across all calls made during the loop — the
 74	 * authoritative record the caller should use, not the model's prose.
 75	 */
 76	export function makeSourcingToolRunner(
 77	  campaign: Campaign,
 78	  existing: Candidate[],
 79	  weights: ScoringWeights,
 80	  githubToken: string,
 81	) {
 82	  const found: Candidate[] = [];
 83	
 84	  async function run(
 85	    name: string,
 86	    args: Record<string, unknown>,
 87	  ): Promise<{ ok: boolean; content?: unknown; error?: string }> {
 88	    if (name !== "search_candidates") return { ok: false, error: "Unknown tool." };
 89	
 90	    const platform = String(args.platform ?? "").trim() as SourcePlatform;
 91	    const query = String(args.query ?? "").trim().slice(0, 256);
 92	    const count = Math.min(Math.max(Math.trunc(Number(args.count)) || 5, 1), 10);
 93	    if (!platform) return { ok: false, error: "Missing platform." };
 94	    if (!query) return { ok: false, error: "Missing query." };
 95	
 96	    const alreadySeen = [...existing, ...found];
 97	    let accepted: Candidate[] = [];
 98	    let skippedCount = 0;
 99	
100	    if (platform === "GitHub") {
101	      try {
102	        const users = await searchGithubUsers(query, count, githubToken);
103	        const result = mapGithubCandidates(users, campaign, query, alreadySeen, weights);
104	        accepted = result.accepted;
105	        skippedCount = result.skipped.length;
106	      } catch (err) {
107	        return { ok: false, error: err instanceof Error ? err.message : "GitHub search failed." };
108	      }
109	    } else if (isWebSearchPlatform(platform)) {
110	      const search = await runWebTool("web_search", { query });
111	      if (!search.ok) return { ok: false, error: search.error ?? "Web search failed." };
112	      const content = search.content as { results?: { title: string; url: string; snippet: string }[] } | undefined;
113	      const hits = (content?.results ?? []).slice(0, count);
114	      const leads = hits.map((h) => extractLead(h, platform));
115	      const result = mapWebSearchCandidates(leads, campaign, query, platform, alreadySeen, weights);
116	      accepted = result.accepted;
117	      skippedCount = result.skipped.length;
118	    } else {
119	      return {
120	        ok: false,
121	        error: `${platform || "that platform"} has no external search — Referral/Talent Pool candidates come from the app's own pipeline, not a search.`,
122	      };
123	    }
124	
125	    found.push(...accepted);
126	    const summary: SearchSummary[] = accepted.map((c) => ({
127	      id: c.id,
128	      name: c.name,
129	      currentTitle: c.currentTitle,
130	      currentCompany: c.currentCompany,
131	      location: c.location,
132	      matchScore: c.matchScore,
133	      sourcePlatform: c.sourcePlatform,
134	      url: c.githubUrl || c.linkedinUrl || c.sourceUrl || "",
135	      techStack: c.techStack,
136	      recentActivity: c.recentActivity,
137	    }));
138	    return { ok: true, content: { platform, query, found: summary, skippedByDedupe: skippedCount } };
139	  }
140	
141	  return { run, getFound: (): Candidate[] => found };
142	}
