 56	function buildPrompt(campaign: Campaign, count: number): string {
 57	  const jd = campaign.jobAnalysis;
 58	  return [
 59	    `Role: ${jd.title} (${jd.seniority}, ${jd.department})`,
 60	    `Location: ${jd.locationType}${jd.regions.length ? ` — ${jd.regions.join("/")}` : ""}`,
 61	    `Required skills: ${jd.requiredSkills.join(", ") || "n/a"}`,
 62	    `Nice-to-have: ${jd.niceToHaveSkills.join(", ") || "n/a"}`,
 63	    jd.minYearsExperience != null ? `Minimum experience: ${jd.minYearsExperience} years` : "",
 64	    jd.companyStageTarget.length ? `Target company stage: ${jd.companyStageTarget.join(", ")}` : "",
 65	    jd.industryExperience.length ? `Industry experience: ${jd.industryExperience.join(", ")}` : "",
 66	    "",
 67	    `Find and draft outreach for ${count} real candidates for this role.`,
 68	  ]
 69	    .filter(Boolean)
 70	    .join("\n");
 71	}
