 73	/** Parse the model's final JSON, tolerant of stray text/markdown fences around it. */
 74	function parseDrafts(text: string): { candidateId: string; subject: string; body: string }[] {
 75	  const match = text.match(/\{[\s\S]*\}/);
 76	  if (!match) return [];
 77	  try {
 78	    const parsed = JSON.parse(match[0]) as { drafts?: unknown };
 79	    if (!Array.isArray(parsed.drafts)) return [];
 80	    return parsed.drafts
 81	      .filter(
 82	        (d): d is { candidateId: string; subject: string; body: string } =>
 83	          !!d &&
 84	          typeof d === "object" &&
 85	          typeof (d as Record<string, unknown>).candidateId === "string" &&
 86	          typeof (d as Record<string, unknown>).subject === "string" &&
 87	          typeof (d as Record<string, unknown>).body === "string",
 88	      )
 89	      .map((d) => ({ candidateId: d.candidateId, subject: d.subject.slice(0, 255), body: d.body.slice(0, 5_000) }));
 90	  } catch {
 91	    return [];
 92	  }
 93	}
