 95	export async function POST(req: NextRequest) {
 96	  const prodBlock = prodFailClosed();
 97	  if (prodBlock) return prodBlock;
 98	
 99	  const supabase = supabaseEnabled ? await getServerSupabase() : null;
100	  let userId: string | null = null;
101	  if (supabaseEnabled) {
102	    if (!supabase) return NextResponse.json({ ok: false, reason: "No Supabase client." }, { status: 500 });
103	    const {
104	      data: { user },
105	    } = await supabase.auth.getUser();
106	    if (!user) return NextResponse.json({ ok: false, reason: "Not authenticated." }, { status: 401 });
107	    userId = user.id;
108	    const { data: role } = await supabase.rpc("current_profile_role");
109	    if (!can(role as Role, "source")) {
110	      return NextResponse.json({ ok: false, reason: "Insufficient permissions." }, { status: 403 });
111	    }
112	  } else if (demoLoginEnabled) {
113	    // Same open-demo cost gate as /api/hermes/chat: env-resident provider keys
114	    // are spendable only by a caller holding a valid demo session.
115	    if (!demoAuthConfigured() || !verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) {
116	      return NextResponse.json({ ok: false, reason: "Sign in to use the sourcing agent." }, { status: 401 });
117	    }
118	  }
119	
120	  const rl = checkRateLimit(rateLimitKey(req, "sourcing-agent", userId), { windowMs: 60_000, max: 10 });
121	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
122	
123	  const validated = await validateBody(req, SourcingAgentSchema, { maxBytes: 200_000 });
124	  if (!validated.ok) return validated.response;
125	  const { count = 5, provider, apiKeyId, model } = validated.data;
126	  const campaign = validated.data.campaign as unknown as Campaign;
127	  const existing = validated.data.existing as unknown as Candidate[];
128	  const weights: ScoringWeights = campaign?.scoringWeights;
129	
130	  if (!campaign?.jobAnalysis || !weights) {
131	    return NextResponse.json({ ok: false, reason: "Malformed campaign payload." }, { status: 400 });
132	  }
133	
134	  const slug = provider as AiProviderSlug;
135	  const vaultKey = await resolveVaultSecret(apiKeyId);
136	  const key = vaultKey || process.env[PROVIDER_ENV[slug]] || "";
137	  if (!key) {
138	    return NextResponse.json({ ok: false, reason: `No API key configured for ${provider}.` });
139	  }
140	
141	  const githubToken = process.env.GITHUB_TOKEN ?? "";
142	  const runner = makeSourcingToolRunner(campaign, existing, weights, githubToken);
143	  const servers: ResolvedMcpServer[] = [
144	    { url: "builtin:sourcing-agent", token: "", tools: SOURCING_TOOL_DEFS, run: runner.run },
145	  ];
146	
147	  const toolModel = model || DEFAULT_MODEL[slug];
148	  const prompt = buildPrompt(campaign, count);
149	  const result =
150	    slug === "anthropic"
151	      ? await runAnthropicWithTools({ model: toolModel, system: SYSTEM_PROMPT, prompt, key, servers, maxRounds: 6 })
152	      : await runOpenAiWithTools({ provider: slug, model: toolModel, system: SYSTEM_PROMPT, prompt, key, servers, maxRounds: 6 });
153	
154	  const foundCandidates = runner.getFound();
155	  if (!result.ok) {
156	    // Even on a loop failure, return whatever real candidates were actually
157	    // found before it failed — the search itself is real and useful even
158	    // without a draft, same "don't throw away real work" posture as the rest
159	    // of this app's real-sourcing paths.
160	    return NextResponse.json({
161	      ok: foundCandidates.length > 0,
162	      reason: result.reason ?? "Agent loop failed.",
163	      candidates: foundCandidates.map((c) => ({ ...c, matchScore: c.matchScore })),
164	    });
165	  }
166	
167	  const drafts = parseDrafts(result.text ?? "");
168	  const byId = new Map(foundCandidates.map((c) => [c.id, c]));
169	  // Only ever attach a draft to a candidate the tool loop actually surfaced —
170	  // never trust a candidateId the model invented that wasn't in a real result.
171	  const candidates = drafts
172	    .map((d) => {
173	      const cand = byId.get(d.candidateId);
174	      if (!cand) return null;
175	      return { ...cand, draftSubject: d.subject, draftBody: d.body };
176	    })
177	    .filter((c): c is Candidate & { draftSubject: string; draftBody: string } => c !== null);
178	
179	  return NextResponse.json({ ok: true, candidates, totalFound: foundCandidates.length });
180	}
