118	/**
119	 * Resolve the caller's enabled MCP servers into connectable servers with their tools.
120	 * The bearer token for each is resolved from the vault server-side (never from the
121	 * browser). http(s) only (SSRF). Servers that fail to connect or expose no tools are
122	 * skipped, so a broken server can't block the chat.
123	 */
124	async function gatherMcpServers(
125	  servers: { url: string; apiKeyId?: string }[],
126	): Promise<ResolvedMcpServer[]> {
127	  const resolved: ResolvedMcpServer[] = [];
128	  for (const s of servers) {
129	    let parsed: URL;
130	    try {
131	      parsed = new URL(s.url);
132	    } catch {
133	      continue;
134	    }
135	    if (parsed.protocol !== "https:" && parsed.protocol !== "http:") continue;
136	    // SSRF guard: block private/loopback/link-local/metadata hosts (and DNS-rebinding)
137	    // before the server ever dials the caller-supplied URL. This server is reused for
138	    // every tool call the model makes during the loop, so this is a repeatable channel
139	    // — not just a one-shot probe.
140	    const guard = await assertPublicUrl(s.url);
141	    if (!guard.ok) continue;
142	    const token = s.apiKeyId ? await resolveVaultSecret(s.apiKeyId) : "";
143	    const conn = await connectAndListTools(s.url, token);
144	    if (conn.ok && conn.tools && conn.tools.length) {
145	      resolved.push({ url: s.url, token, tools: conn.tools });
146	    }
147	  }
148	  return resolved;
149	}
