40	 * tool set) is dispatched directly; the built-in web-research and browser-research
41	 * servers (the BUILTIN_WEB_URL / BUILTIN_BROWSER_URL sentinels) run in-process;
42	 * everything else is brokered to the remote MCP server with its vault token.
43	 * Same {ok, content, error} contract either way.
44	 */
45	async function execTool(
46	  server: ResolvedMcpServer,
47	  name: string,
48	  args: Record<string, unknown>,
49	): Promise<{ ok: boolean; content?: unknown; error?: string }> {
50	  if (server.run) return server.run(name, args);
51	  if (server.url === BUILTIN_WEB_URL) return runWebTool(name, args);
52	  if (server.url === BUILTIN_BROWSER_URL) return runBrowserTool(name, args);
