62	/**
63	 * Map resolved MCP servers' tools to Anthropic tool definitions, plus an index from
64	 * tool name to the owning server. Pure (no I/O) so it is unit-testable. On a tool-name
65	 * collision across servers, the first server wins (later duplicates are dropped).
66	 */
67	export function buildAnthropicToolDefs(servers: ResolvedMcpServer[]): {
68	  toolDefs: AnthropicToolDef[];
69	  owner: Map<string, ResolvedMcpServer>;
70	} {
71	  const toolDefs: AnthropicToolDef[] = [];
72	  const owner = new Map<string, ResolvedMcpServer>();
73	  for (const server of servers) {
74	    for (const t of server.tools) {
75	      if (!t.name || owner.has(t.name)) continue;
76	      owner.set(t.name, server);
77	      const schema =
78	        t.inputSchema && typeof t.inputSchema === "object"
79	          ? (t.inputSchema as Record<string, unknown>)
80	          : { type: "object", properties: {} };
81	      toolDefs.push({ name: t.name, description: t.description ?? "", input_schema: schema });
82	    }
83	  }
84	  return { toolDefs, owner };
85	}
