 40	/* ============================================================================
 41	   Email provider adapters (SERVER ONLY).
 42	   Dry-run is the default everywhere. A real send happens ONLY when: live mode is
 43	   on, the seat's domain is verified, an API key is present in server env, and the
 44	   request is explicitly confirmed live. Resend / SendGrid send via their official
 45	   REST APIs with a single API key. Microsoft Graph / Gmail require per-mailbox
 46	   OAuth (connect flow) and remain a documented seam — never a fake send.
 47	   No scraping, no LinkedIn automation — email only.
 48	   ========================================================================== */
 49	
 50	export interface SendRequest {
 51	  provider: SeatProvider;
 52	  from: string;
 53	  fromName?: string;
 54	  to: string;
 55	  subject: string;
 56	  body: string;
 57	  /** Server-generated opaque recipient link; required for any live delivery. */
 58	  unsubscribeUrl?: string;
 59	}
 60	
 61	export interface SendOutcome {
 62	  status: "sent" | "dry-run" | "error";
 63	  provider: SeatProvider;
 64	  detail: string;
 65	  id?: string;
 66	}
