 68	/** Perform a real send via the provider's official API. Throws on misconfig. */
 69	export async function sendViaProvider(req: SendRequest): Promise<SendOutcome> {
 70	  auditLog("info", "Send attempt", { provider: req.provider, from: req.from, to: req.to });
 71	  if (!req.unsubscribeUrl) {
 72	    return {
 73	      status: "error",
 74	      provider: req.provider,
 75	      detail: "No compliant unsubscribe link is configured for this email.",
 76	    };
 77	  }
 78	  const rendered = renderEmailWithUnsubscribe(req.body, req.unsubscribeUrl);
 79	  switch (req.provider) {
 80	    case "Resend": {
 81	      const key = process.env.RESEND_API_KEY;
 82	      if (!key) {
 83	        auditLog("info", "Resend dry-run: no API key", { to: req.to });
 84	        return { status: "dry-run", provider: req.provider, detail: "No RESEND_API_KEY, dry-run only." };
 85	      }
 86	      const res = await fetch("https://api.resend.com/emails", {
 87	        method: "POST",
 88	        signal: AbortSignal.timeout(15_000),
 89	        headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
 90	        body: JSON.stringify({
 91	          from: req.fromName ? `${req.fromName} <${req.from}>` : req.from,
 92	          to: [req.to],
 93	          subject: req.subject,
 94	          text: rendered.text,
 95	          html: rendered.html,
 96	          headers: rendered.headers,
 97	        }),
 98	      });
 99	      const json = await res.json().catch(() => ({}));
100	      if (!res.ok) {
101	        auditLog("error", "Resend send failed", { status: res.status, to: req.to });
102	        return { status: "error", provider: req.provider, detail: `Resend send error ${res.status}.` };
103	      }
104	      auditLog("info", "Resend send succeeded", { to: req.to, id: json?.id });
105	      return { status: "sent", provider: req.provider, detail: "Sent via Resend.", id: json?.id };
106	    }
107	    case "SendGrid": {
108	      const key = process.env.SENDGRID_API_KEY;
109	      if (!key) {
110	        auditLog("info", "SendGrid dry-run: no API key", { to: req.to });
111	        return { status: "dry-run", provider: req.provider, detail: "No SENDGRID_API_KEY, dry-run only." };
112	      }
113	      const res = await fetch("https://api.sendgrid.com/v3/mail/send", {
114	        method: "POST",
115	        signal: AbortSignal.timeout(15_000),
116	        headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
117	        body: JSON.stringify({
118	          personalizations: [{ to: [{ email: req.to }] }],
119	          from: { email: req.from, name: req.fromName },
120	          subject: req.subject,
121	          content: [
122	            { type: "text/plain", value: rendered.text },
123	            { type: "text/html", value: rendered.html },
124	          ],
125	          headers: rendered.headers,
126	        }),
127	      });
128	      if (!res.ok) {
129	        const txt = await res.text().catch(() => "");
130	        auditLog("error", "SendGrid send failed", { status: res.status, to: req.to, body: redactSecrets(redactEmail(txt.slice(0, 500))) });
131	        return { status: "error", provider: req.provider, detail: `SendGrid send error ${res.status}.` };
132	      }
133	      auditLog("info", "SendGrid send succeeded", { to: req.to });
134	      return { status: "sent", provider: req.provider, detail: "Sent via SendGrid." };
135	    }
136	    case "Microsoft Graph":
137	    case "Gmail API": {
138	      // OAuth providers are handled by sendViaOAuthProvider in the outreach send
139	      // route so the stored token can be resolved server-side.
140	      const detail = `${req.provider} must be sent via the OAuth adapter. Dry-run.`;
141	      auditLog("info", "OAuth provider dry-run", { provider: req.provider, to: req.to });
142	      return { status: "dry-run", provider: req.provider, detail };
143	    }
144	    default:
145	      auditLog("error", "Unknown email provider", { provider: req.provider });
146	      return { status: "dry-run", provider: req.provider, detail: "Unknown provider, dry-run only." };
147	  }
148	}
