 11	import { checkSeamlessAuth } from "@/lib/sourcing/seamless";
 12	
 13	const ApiKeyTestSchema = z.object({
 14	  provider: z.string().max(80).optional(),
 15	  value: z.string().max(1000).optional(),
 16	  id: z.string().uuid().optional(),
 17	});
