  2	// (LinkedIn, Stack Overflow, Dribbble, Behance). READ-ONLY: reuses the existing
  3	// compliant web_search tool (src/lib/ai/web-tools.ts) — honest bot User-Agent, no
  4	// login/cookies/stealth, SSRF-guarded — scoped with a `site:` filter per platform.
  5	//
  6	// Honest limitation: search results give a title/url/snippet, not a structured
  7	// profile. Name and current title are best-effort, extracted from the result text
  8	// or the profile URL slug when parsing fails — never fabricated. Email is always
  9	// blank; finding it is a separate enrichment step (same policy as GitHub sourcing).
 10	
 11	import type { SourcePlatform } from "@/lib/types";
 12	
 13	export interface SearchHit {
 14	  title: string;
 15	  url: string;
 16	  snippet: string;
 17	}
 18	
 19	export interface WebLead {
 20	  name: string;
 21	  title: string;
 22	  company: string;
 23	  url: string;
 24	  snippet: string;
 25	}
 26	
 27	/** Platforms real-sourced via a site:-scoped web search rather than a dedicated API. */
 28	export type WebSearchPlatform = "LinkedIn" | "Stack Overflow" | "Dribbble" | "Behance";
 29	
 30	const WEB_SEARCH_PLATFORMS = new Set<SourcePlatform>(["LinkedIn", "Stack Overflow", "Dribbble", "Behance"]);
 31	
 32	/** True for platforms sourced through the web-search discovery path in this module. */
 33	export function isWebSearchPlatform(platform: SourcePlatform): platform is WebSearchPlatform {
 34	  return WEB_SEARCH_PLATFORMS.has(platform);
 35	}
 36	
 37	const PLATFORM_DOMAINS: Record<WebSearchPlatform, string> = {
 38	  LinkedIn: "linkedin.com/in",
 39	  "Stack Overflow": "stackoverflow.com/users",
 40	  Dribbble: "dribbble.com",
 41	  Behance: "behance.net",
 42	};
 43	
 44	const TITLE_SUFFIX_PATTERNS: Record<WebSearchPlatform, RegExp> = {
 45	  LinkedIn: /\s*[|\-]\s*LinkedIn\s*$/i,
 46	  "Stack Overflow": /\s*[|\-]\s*Stack Overflow\s*$/i,
 47	  // Dribbble/Behance commonly read "Name on Dribbble" with no leading | or -,
 48	  // unlike LinkedIn/Stack Overflow — so that delimiter is optional here.
 49	  Dribbble: /\s*(?:[|\-]\s*)?(on\s+)?Dribbble('s)?(\s+profile)?\s*$/i,
 50	  Behance: /\s*(?:[|\-]\s*)?(on\s+)?Behance('s)?(\s+profile)?\s*$/i,
 51	};
 52	
 53	/** Scope a base boolean/keyword query (e.g. campaign.sourcingStrategy.linkedinBoolean) to one platform. */
 54	export function buildWebQuery(platform: WebSearchPlatform, baseQuery: string): string {
 55	  return `site:${PLATFORM_DOMAINS[platform]} ${baseQuery}`.trim();
 56	}
 57	
 58	function titleCase(words: string): string {
 59	  return words
 60	    .split(/\s+/)
 61	    .filter(Boolean)
 62	    .map((w) => w[0]!.toUpperCase() + w.slice(1))
 63	    .join(" ");
 64	}
 65	
 66	/** Best-effort name from a profile URL slug, e.g. dribbble.com/jane-doe-42 -> "Jane Doe". */
 67	function nameFromSlug(url: string): string {
 68	  try {
 69	    const segments = new URL(url).pathname.split("/").filter(Boolean);
 70	    const slug = segments[segments.length - 1] ?? "";
 71	    const cleaned = slug.replace(/-[a-f0-9]{4,}$/i, "").replace(/[-_]+/g, " ").trim();
 72	    return cleaned ? titleCase(cleaned) : "";
 73	  } catch {
 74	    return "";
 75	  }
 76	}
 77	
 78	/** A raw url-slug ("jane-doe-4471"), not prose — prefer the title-cased slug over this. */
 79	function looksLikeSlug(s: string): boolean {
 80	  return /^[a-z0-9]+(?:-[a-z0-9]+)+$/.test(s);
 81	}
 82	
 83	/**
 84	 * Extract a best-effort lead from one search hit. Never throws, never fabricates —
 85	 * falls back to the URL slug or the raw (truncated) title when structured parsing
 86	 * doesn't find a clean "Name - Title - Company" pattern.
 87	 */
 88	export function extractLead(hit: SearchHit, platform: WebSearchPlatform): WebLead {
 89	  const cleanedTitle = hit.title.replace(TITLE_SUFFIX_PATTERNS[platform], "").trim();
 90	  const parts = cleanedTitle
 91	    .split(/\s+-\s+/)
 92	    .map((p) => p.trim())
 93	    .filter(Boolean);
 94	  // Common LinkedIn/profile title shape: "Name - Title - Company". Take what's there;
 95	  // never invent a company or title the result text doesn't actually contain. When the
 96	  // leading segment is itself a raw slug (search engine had no real title to show),
 97	  // prefer the title-cased URL slug over dumping the slug in as a "name".
 98	  const rawName = parts[0];
 99	  const name =
100	    (rawName && !looksLikeSlug(rawName) ? rawName : nameFromSlug(hit.url)) ||
101	    rawName ||
102	    cleanedTitle.slice(0, 60) ||
103	    "Unknown";
104	  const title = parts[1] || hit.snippet.slice(0, 120);
105	  const company = parts[2] || "";
106	  return { name, title, company, url: hit.url, snippet: hit.snippet.slice(0, 300) };
107	}
