169	/** `fetch` with a hard abort deadline so a hung provider cannot stall the route. */
170	async function fetchWithTimeout(input: string, init: RequestInit, timeoutMs = 10_000): Promise<Response> {
171	  const controller = new AbortController();
172	  const timer = setTimeout(() => controller.abort(), timeoutMs);
173	  try {
174	    return await fetch(input, { ...init, signal: controller.signal });
175	  } finally {
176	    clearTimeout(timer);
177	  }
178	}
