233	  if (integration.mode === "mock") {
234	    return {
235	      ok: true,
236	      latencyMs: 0,
237	      message: `${integration.name}: mock adapter. Sample data only, no live call. Switch to Live to validate real credentials.`,
238	    };
239	  }
240	  return {
241	    ok: true,
242	    latencyMs: 0,
243	    message: `${integration.name}: live credentials stored, and will be validated on the next sync.`,
