   1	// Real candidate sourcing via the GitHub Users Search API. READ-ONLY: this only
   2	// searches and reads public profiles; it never writes to GitHub. The caller (the
   3	// /api/source route) supplies a token resolved server-side and never logs it.
   4	//
   5	// Keyless by default: GitHub's REST API allows fully anonymous requests (no signup,
   6	// no token) at 60 req/hour per IP, with tighter limits on the search endpoint. A
   7	// GITHUB_TOKEN is optional and only raises the ceiling (5,000 req/hour) — it is
   8	// never required to get real results.
   9	//
  10	// Honest limitation: GitHub exposes a public profile, not always an email. We take
  11	// the public email when present and otherwise leave it blank — the candidate is a
  12	// real person you found; finding their email is a separate enrichment step.
  13	
  14	const GH_API = "https://api.github.com";
  15	
  16	export interface GithubUser {
  17	  login: string;
  18	  name: string | null;
  19	  email: string | null;
  20	  company: string | null;
  21	  location: string | null;
  22	  bio: string | null;
  23	  blog: string | null;
  24	  htmlUrl: string;
  25	  publicRepos: number;
  26	  followers: number;
  27	  createdAt: string | null; // account creation — a rough proxy for time in the field
  28	  topLanguage: string | null; // parsed from the search query's `language:` filter
  29	}
  30	
  31	async function gh(path: string, token: string): Promise<unknown> {
  32	  const headers: Record<string, string> = {
  33	    Accept: "application/vnd.github+json",
  34	    "X-GitHub-Api-Version": "2022-11-28",
  35	    "User-Agent": "aria-sourcing",
  36	  };
  37	  if (token) headers.Authorization = `Bearer ${token}`;
  38	  const res = await fetch(`${GH_API}${path}`, {
  39	    headers,
  40	    // Single-use signal per call; the route bounds the overall work.
  41	    signal: AbortSignal.timeout(15_000),
  42	  });
  43	  if (!res.ok) throw new Error(`GitHub API ${res.status}`);
  44	  return res.json();
  45	}
