  47	/** Fetch and map one GitHub user by login — shared by the search loop below
  48	 *  (each search hit is resolved to a full profile) and getGithubUser (a direct
  49	 *  single-user lookup). Throws on any fetch failure; callers decide how to
  50	 *  handle it (searchGithubUsers skips it and keeps the rest of the batch,
  51	 *  getGithubUser reports a 404 as "not found" and re-throws anything else). */
  52	async function fetchGithubUser(login: string, token: string, topLanguage: string | null): Promise<GithubUser> {
  53	  const u = (await gh(`/users/${encodeURIComponent(login)}`, token)) as Record<string, unknown>;
  54	  return {
  55	    login: String(u.login ?? login),
  56	    name: (u.name as string) ?? null,
  57	    email: (u.email as string) ?? null,
  58	    company: (u.company as string) ?? null,
  59	    location: (u.location as string) ?? null,
  60	    bio: (u.bio as string) ?? null,
  61	    blog: (u.blog as string) ?? null,
  62	    htmlUrl: String(u.html_url ?? `https://github.com/${login}`),
  63	    publicRepos: Number(u.public_repos ?? 0),
  64	    followers: Number(u.followers ?? 0),
  65	    createdAt: (u.created_at as string) ?? null,
  66	    topLanguage,
  67	  };
  68	}
