  70	/**
  71	 * Search GitHub users and resolve each to a public profile.
  72	 *
  73	 * `query` is a GitHub search qualifier string, e.g.
  74	 * `language:typescript location:london followers:>50`. `count` is capped at 20.
  75	 * `token` is optional — pass "" to run fully anonymous (60 req/hour); a real token
  76	 * raises that to 5,000 req/hour. Per-user detail calls are sequential and bounded
  77	 * by `count`.
  78	 */
  79	export async function searchGithubUsers(
  80	  query: string,
  81	  count: number,
  82	  token = "",
  83	): Promise<GithubUser[]> {
  84	  const perPage = Math.min(Math.max(Math.trunc(count) || 1, 1), 20);
  85	  const search = (await gh(
  86	    `/search/users?q=${encodeURIComponent(query)}&per_page=${perPage}`,
  87	    token,
  88	  )) as { items?: { login?: string }[] };
  89	  const logins = (search.items ?? [])
  90	    .map((u) => u.login)
  91	    .filter((l): l is string => typeof l === "string" && l.length > 0)
  92	    .slice(0, perPage);
  93	
  94	  const lang = query.match(/language:([A-Za-z0-9+#.\-]+)/i)?.[1] ?? null;
  95	
  96	  const users: GithubUser[] = [];
  97	  for (const login of logins) {
  98	    try {
  99	      users.push(await fetchGithubUser(login, token, lang));
 100	    } catch {
 101	      // Skip a user whose detail fetch fails; keep the rest of the batch.
 102	    }
 103	  }
 104	  return users;
 105	}
