 107	/**
 108	 * Resolve a single, specific GitHub user by exact login — the operator handed
 109	 * Aria a real person instead of a search. Same public-profile mapping as
 110	 * searchGithubUsers; topLanguage is null (there's no search query to parse a
 111	 * `language:` filter from). Returns null on a 404 (no such user); any other
 112	 * failure (network, rate limit, ...) throws.
 113	 */
 114	export async function getGithubUser(login: string, token = ""): Promise<GithubUser | null> {
 115	  try {
 116	    return await fetchGithubUser(login, token, null);
 117	  } catch (err) {
 118	    if (err instanceof Error && /GitHub API 404/.test(err.message)) return null;
 119	    throw err;
 120	  }
 121	}
 100	export function roleFamily(jd: JobAnalysis): RoleFamily {
 101	  const hay = `${jd.title} ${jd.department} ${jd.requiredSkills.join(" ")} ${jd.industryExperience.join(" ")}`;
 102	  const dept = jd.department.toLowerCase();
 103	
 104	  if (FINANCE_SIGNALS.test(hay) || /consulting|finance|banking/.test(dept)) return "finance";
 105	  if (/design/.test(dept) || /\b(figma|ux|ui|design systems|prototyping)\b/i.test(hay)) return "design";
 106	  if (/\bdata\b|ml|machine learning|analytics/.test(dept) || /\b(tensorflow|pytorch|spark|dbt|snowflake|airflow|llm|rag)\b/i.test(hay)) return "data";
 107	  if (/sales|revenue/.test(dept) || /\b(account executive|quota|pipeline generation|sdr|bdr)\b/i.test(hay)) return "sales";
 108	  if (/product/.test(dept) && !/engineer/i.test(jd.title)) return "product";
 109	  if (/marketing|growth/.test(dept)) return "marketing";
 110	  if (/platform|engineering/.test(dept) || CODE_SKILLS.test(hay) || /engineer|developer|architect/i.test(jd.title)) return "software";
 111	  return "generic";
 112	}
