 543	export function buildSourcingStrategy(jd: JobAnalysis): SourcingStrategy {
 544	  const topSkills = jd.requiredSkills.slice(0, 4);
 545	  const region = jd.regions[0];
 546	  const locationQualifier = region && !NON_LOCATION_REGIONS.has(region) ? ` location:${region}` : "";
 547	  // Note: only user-search qualifiers are valid here (language:, location:,
 548	  // followers:, repos:, created:). Repo qualifiers like `stars:` silently zero
 549	  // out the whole query on /search/users.
 550	  const githubQueries: GithubQuery[] = topSkills.slice(0, 3).map((skill, i) => ({
 551	    label: `${skill} contributors`,
 552	    query: `language:${skill.replace(/\s+/g, "")}${locationQualifier} followers:>40 ${
 553	      i === 0 ? "repos:>10" : "repos:>5"
 554	    }`,
 555	    estimatedResults: 120 + i * 60,
 556	  }));
 557	
 558	  const linkedinBoolean = `("${jd.title}" OR "${jd.seniority} ${jd.department}") AND (${topSkills
 559	    .map((s) => `"${s}"`)
 560	    .join(" OR ")}) AND (${jd.regions.map((r) => `"${r}"`).join(" OR ")}) NOT "recruiter"`;
 561	
 562	  const profile = roleProfile(jd);
 563	  return {
 564	    // Platform mix adapts to the role family (code roles → GitHub-led; everything
 565	    // else → professional networks first).
 566	    primaryPlatforms: profile.platforms.slice(0, 2),
 567	    secondaryPlatforms: profile.platforms.slice(2).length ? profile.platforms.slice(2) : ["Referral"],
 568	    githubQueries,
 569	    linkedinBoolean,
 570	    stackOverflowTags: topSkills.map((s) => s.toLowerCase().replace(/\s+/g, "-")),
 571	    geoTargets: jd.regions,
 572	    excludedCompanies: ["Granite Industries", "Eastfield Group"],
 573	    targetCompanyStages: jd.companyStageTarget,
 574	  };
 575	}
